(()=>{'use strict';
const AMP_KEY='amp-personal-space-v1', PROPERTY_KEY='property-manager-v1';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>Array.from(root.querySelectorAll(q));
const iconPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-7h6v7"/>',building:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 7h1M14 7h1M9 11h1M14 11h1M9 15h1M14 15h1M10 21v-4h4v4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',folder:'<path d="M3 6a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',upRight:'<path d="M7 17 17 7M7 7h10v10"/>',chevronR:'<path d="m9 18 6-6-6-6"/>',chevronL:'<path d="m15 18-6-6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',checkCircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.7 5.7l2.1 2.1m8.4 8.4 2.1 2.1M18.3 5.7l-2.1 2.1m-8.4 8.4-2.1 2.1"/><circle cx="12" cy="12" r="4"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',edit:'<path d="m16 4 4 4-12 12H4v-4zM14 6l4 4"/>',trash:'<path d="M4 7h16M10 4h4m-8 3 1 14h10l1-14M10 11v6m4-6v6"/>',archive:'<rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v11h14V9M10 13h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M5 17v4h14v-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4 4l2 2m12 12 2 2M2 12h2m16 0h2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20.5 14A8.5 8.5 0 0 1 10 3.5 9 9 0 1 0 20.5 14z"/>',chart:'<path d="M4 20V4M4 20h17M8 16l4-5 3 2 5-7"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 10h18M15 15h3M7 6V4h12"/>',file:'<path d="M6 3h8l5 5v13H6zM14 3v6h5M9 13h7M9 17h7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',flag:'<path d="M5 21V4m0 1q4-3 8 0t7 0v11q-3 3-7 0t-8 0"/>',trophy:'<path d="M8 4h8v7a4 4 0 0 1-8 0zM8 6H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 15v4m-5 2h10"/>',link:'<path d="M10 13a5 5 0 0 0 7.2 0l2-2a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7.2 0l-2 2a5 5 0 0 0 7 7l2-2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0v5l-2 3h16l-2-3zm-8 11a2 2 0 0 0 4 0"/>',repeat:'<path d="M7 7h13l-3-3m3 3-3 3M17 17H4l3 3m-3-3 3-3"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',sparkle:'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z"/>',note:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',paperclip:'<path d="m20 11-8.5 8.5a6 6 0 0 1-8.5-8.5l9-9a4 4 0 0 1 5.7 5.7l-9 9a2 2 0 0 1-2.8-2.8l8.2-8.2"/>',rotate:'<path d="M3 12a9 9 0 1 0 3-7l-3 3M3 3v5h5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',house:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-7h6v7"/>',fire:'<path d="M12 22c5 0 8-3.4 8-8 0-4-2-6-5-9 0 4-2 5-3 6-1-3-1-6-3-9C7 6 4 9 4 14c0 4.6 3 8 8 8"/>',trend:'<path d="m3 17 6-6 4 4 8-9M15 6h6v6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',external:'<path d="M13 4h7v7M20 4l-9 9M20 14v6H4V4h6"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M4 6h.01M4 12h.01M4 18h.01"/>',moveUp:'<path d="m6 14 6-6 6 6"/>',moveDown:'<path d="m6 10 6 6 6-6"/>',calendarCheck:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18m5 5 2 2 4-4"/>'};
const I=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(Number.isFinite(Number(n))?Number(n):0);
const num=n=>Number.isFinite(Number(n))?Math.max(0,Number(n)):0;
const iso=d=>{let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const today=()=>iso(new Date()), parseDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')&&!isNaN(new Date(s+'T12:00:00').getTime())?new Date(s+'T12:00:00'):null;
const formatDate=(s,opts={day:'numeric',month:'short',year:'numeric'})=>{const d=parseDate(s);return d?new Intl.DateTimeFormat('en-GB',opts).format(d):'Not set'};
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const addDays=(date,n)=>{let d=new Date(date);d.setDate(d.getDate()+n);return d};
const startMonth=(d)=>new Date(d.getFullYear(),d.getMonth(),1,12);
const shiftMonth=(d,n)=>new Date(d.getFullYear(),d.getMonth()+n,1,12);
const weekStart=d=>{let o=new Date(d);o.setDate(d.getDate()-(d.getDay()+6)%7);return o};
const percent=(a,b)=>b>0?Math.round(a/b*100):0;
const pageNames={home:'Dashboard',property:'Property',discipline:'Discipline',admin:'Life Admin',goals:'Goals'};
const pageIcons={home:'home',property:'building',discipline:'calendarCheck',admin:'folder',goals:'target'};
const defaultHabits=()=>[{id:'gym',name:'Gym',color:'#32835f'},{id:'portfolio',name:'Portfolio',color:'#6d9bd8'},{id:'journal',name:'Journal',color:'#ad8bd0'},{id:'screen',name:'<4h screen time',color:'#d4a667'}];
const freshApp=()=>({version:1,habits:defaultHabits(),checks:{},goals:[],cases:[]});
let app=freshApp(),property={properties:[],transactions:[]};
function load(){try{let s=JSON.parse(localStorage.getItem(AMP_KEY)||'null');if(s&&typeof s==='object'&&Array.isArray(s.habits)&&Array.isArray(s.goals)&&Array.isArray(s.cases)&&s.checks&&typeof s.checks==='object'){app={version:1,habits:s.habits,checks:s.checks,goals:s.goals,cases:s.cases}}}catch(e){}try{let s=JSON.parse(localStorage.getItem(PROPERTY_KEY)||'null');if(s&&Array.isArray(s.properties)&&Array.isArray(s.transactions))property={properties:s.properties,transactions:s.transactions}}catch(e){}}
load();
function save(){try{localStorage.setItem(AMP_KEY,JSON.stringify(app));localStorage.setItem(PROPERTY_KEY,JSON.stringify(property));return true}catch(e){toast('Could not save. Storage may be full.');return false}}
const ui={page:'home',selectedDate:today(),calendarAnchor:startMonth(new Date()),calendarView:'month',goalId:null,goalTab:'journey',caseId:null,caseFilter:'active',propertyId:null,modal:null};
let toastTimer;
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function header(){const now=new Date();$('#todayDate').textContent=new Intl.DateTimeFormat('en-GB',{weekday:'short',day:'numeric',month:'short'}).format(now);$('#breadcrumb').textContent='AMP / '+ui.page.toUpperCase();$('#topTitle').textContent=pageNames[ui.page]||'Dashboard';$('#settingsIcon').innerHTML=I('settings');const nav=Object.keys(pageNames);$('#desktopNav').innerHTML=nav.map(p=>`<button class="side-item ${ui.page===p?'active':''}" data-page="${p}" ${ui.page===p?'aria-current="page"':''}>${I(pageIcons[p])}<span>${pageNames[p]}</span></button>`).join('');$('#mobileNav').innerHTML=nav.map(p=>`<button class="nav-item ${ui.page===p?'active':''}" data-page="${p}" ${ui.page===p?'aria-current="page"':''}>${I(pageIcons[p])}<span>${p==='home'?'Home':p==='discipline'?'Habits':p==='admin'?'Admin':pageNames[p]}</span></button>`).join('')}
function go(p){ui.page=pageNames[p]?p:'home';ui.caseId=null;ui.goalId=null;ui.propertyId=null;history.replaceState(null,'','#'+ui.page);render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){header();let html=ui.page==='home'?homeView():ui.page==='property'?propertyView():ui.page==='discipline'?disciplineView():ui.page==='admin'?adminView():goalsView();$('#main').innerHTML=`<div class="page">${html}<p class="footer-note">AMP · Made for your own rhythm. Data is stored in this browser, not in your GitHub repository.</p></div>`;if(ui.page==='admin'&&ui.caseId)renderAttachments(ui.caseId)}
const metric=(label,value,note='',ic='chart',icClass='')=>`<div class="card metric-card"><div class="round-icon ${icClass}">${I(ic)}</div><span class="muted-label">${E(label)}</span><div class="metric-value">${E(value)}</div>${note?`<div class="metric-note">${E(note)}</div>`:''}</div>`;
const cta=(label,act,extra='')=>`<button class="action-btn" data-action="${act}" ${extra}>${I('plus')} ${E(label)}</button>`;
function homeView(){const p=propertyStats(),todayChecks=checkCount(today()),adminAction=app.cases.filter(c=>c.status==='action').length,pending=app.cases.filter(c=>c.status==='waiting').length,goalDone=app.goals.filter(g=>g.steps&&g.steps.length&&g.steps.every(s=>s.done)).length,goalsN=app.goals.length;const modules=[{key:'property',name:'Property',desc:property.properties.length?`${property.properties.length} properties · ${money(p.equity)} estimated equity`:'Manage your properties and finances',ic:'building',icClass:'cream'},{key:'discipline',name:'Discipline',desc:`${todayChecks}/${app.habits.length} habits checked today`,ic:'calendarCheck',icClass:'blue'},{key:'admin',name:'Life Admin',desc:`${adminAction} need action · ${pending} waiting`,ic:'folder',icClass:'purple'},{key:'goals',name:'Goals',desc:`${goalDone} of ${goalsN} journeys completed`,ic:'target',icClass:'rose'}];const cases=app.cases.filter(c=>c.status==='action'||c.status==='scheduled').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,3);return `<section class="welcome-hero"><div><span class="eyebrow">YOUR PERSONAL COMMAND CENTRE</span><h1>Everything moving.<br>One place.</h1><p>Your properties, habits, life admin and personal journeys — organised around you.</p></div><div class="hero-decoration" aria-hidden="true"><span></span></div></section><div class="section-top"><div><h2>Your workspace</h2><p class="brief-note">Four spaces. One seamless system.</p></div></div><div class="module-grid">${modules.map(m=>`<button class="module-card" data-page="${m.key}"><span class="arrow-corner">${I('upRight')}</span><span class="round-icon ${m.icClass}">${I(m.ic)}</span><span><span class="card-title">${m.name}</span><span class="card-desc" style="display:block">${E(m.desc)}</span></span></button>`).join('')}</div><div class="section-top"><h2>At a glance</h2><span class="muted-label">LIVE FROM YOUR DATA</span></div><div class="metric-grid">${metric('PROPERTY EQUITY',property.properties.length?money(p.equity):'—','Estimated value less debt','building','cream')}${metric('HABITS TODAY',`${todayChecks}/${app.habits.length}`,'Daily check-ins','calendarCheck','blue')}${metric('OPEN ADMIN',String(adminAction),'Cases needing action','folder','purple')}${metric('GOALS ACTIVE',String(app.goals.filter(g=>!g.archived).length),'Journeys you created','target','rose')}</div><div class="section-top"><h2>Next on your radar</h2><button class="section-link" data-page="admin">View Life Admin ${I('arrow')}</button></div><div class="home-bottom"><div class="card"><div class="small-row"><h3 style="margin:0">Admin queue</h3><span class="tag ${adminAction?'amber':'gray'}">${adminAction} to do</span></div>${cases.length?cases.map(c=>`<button class="home-line" style="width:100%;background:none;border-left:0;border-right:0;border-top:0;text-align:left;cursor:pointer" data-action="openCase" data-id="${E(c.id)}"><div><strong class="item-title">${E(c.title)}</strong><div class="line-sub">${E(c.nextAction||'Open case for details')}</div></div><span class="line-right">${c.due?formatDate(c.due,{day:'numeric',month:'short'}):I('chevronR')}</span></button>`).join(''):`<div class="empty-state" style="padding:27px 8px">${I('checkCircle')}<h3>All clear for now</h3><p>Your next admin actions will appear here.</p></div>`}</div><div class="card"><div class="small-row"><h3 style="margin:0">Keep the momentum</h3><span class="tag">${todayChecks} ticks</span></div><div class="home-line"><div><strong class="item-title">Daily discipline</strong><div class="line-sub">Check your habits for today</div></div><button class="icon-btn" data-page="discipline" aria-label="Open discipline">${I('chevronR')}</button></div><div class="home-line"><div><strong class="item-title">Goal journeys</strong><div class="line-sub">Move a checkpoint forward</div></div><button class="icon-btn" data-page="goals" aria-label="Open goals">${I('chevronR')}</button></div></div></div>`}
// PROPERTY: reads/writes the same property-manager-v1 storage used by the original app.
function monthsBetween(a,b){let n=(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth();if(b.getDate()<a.getDate())n--;return Math.max(0,n)}
function mortgageEstimate(p){const m=p.model||{},d=parseDate(m.baseDate);if(!d||m.baseBalance===''||m.baseBalance===undefined||m.rate===''||m.rate===undefined||m.monthlyPayment===''||m.monthlyPayment===undefined)return {balance:num(p.mortgage),estimated:false};let bal=num(m.baseBalance),r=num(m.rate)/1200,pay=num(m.monthlyPayment)+num(m.overpayment);for(let i=0,n=Math.min(1200,monthsBetween(d,new Date()));i<n&&bal>0;i++)bal=Math.max(0,bal*(1+r)-pay);return{balance:bal,estimated:true}}
function valueEstimate(p){const m=p.model||{},d=parseDate(m.valueDate),g=Number(m.growth);if(!d||m.baseValue===''||m.baseValue===undefined||m.growth===''||m.growth===undefined||!Number.isFinite(g))return{value:num(p.value),estimated:false};const years=(new Date()-d)/(365.2425*864e5);return{value:num(m.baseValue)*Math.pow(1+g/100,years),estimated:true}}
function propertyStats(){const vals=property.properties.map(p=>({p,m:mortgageEstimate(p),v:valueEstimate(p)}));const value=vals.reduce((a,x)=>a+x.v.value,0),debt=vals.reduce((a,x)=>a+x.m.balance,0),rent=vals.reduce((a,x)=>a+num(x.p.rent),0),monthlyMortgage=vals.reduce((a,x)=>a+num(x.p.payment),0),month=today().slice(0,7),expense=property.transactions.filter(t=>t.type==='expense'&&t.date.slice(0,7)===month).reduce((a,t)=>a+num(t.amount),0);return{value,debt,rent,monthlyMortgage,expense,cash:rent-monthlyMortgage-expense,equity:value-debt,ltv:value?debt/value*100:0,vals}}
function propertyView(){const s=propertyStats();if(ui.propertyId){const p=property.properties.find(p=>p.id===ui.propertyId);if(p)return propertyDetail(p,s);ui.propertyId=null}return `<div class="page-intro"><div><span class="eyebrow">PROPERTY MANAGEMENT</span><h1>Portfolio overview.</h1><p>Keep your homes, mortgage projections and real transactions in one place.</p></div>${cta('Add property','newProperty')}</div><div class="metric-grid">${metric('TOTAL VALUE',money(s.value),'Valuation estimate','house','cream')}${metric('MORTGAGE DEBT',money(s.debt),'Projected where configured','wallet','blue')}${metric('MONTHLY RENT',money(s.rent),'Scheduled income','trend','purple')}${metric('MONTHLY CASH FLOW',money(s.cash),'Before tax and unrecorded costs','chart')}</div><div class="section-top"><h2>Your properties</h2><span class="muted-label">${property.properties.length} PROPERTIES</span></div><div class="card">${property.properties.length?property.properties.map(p=>{const v=valueEstimate(p),m=mortgageEstimate(p);return `<div class="property-row"><div><strong>${E(p.name)}</strong><div class="secondary-line">${money(v.value)} estimated value · ${money(m.balance)} mortgage<br>${money(p.rent)} rent / month · ${money(p.payment)} mortgage payment</div><div class="pill-row spacer-top"><span class="tag ${v.estimated?'':'gray'}">${v.estimated?'Projected':'Recorded value'}</span><span class="tag gray">${money(v.value-m.balance)} equity</span></div></div><button class="outline-btn mini-btn" data-action="openProperty" data-id="${E(p.id)}">Open ${I('chevronR')}</button></div>`}).join(''):`<div class="empty-state"><div class="round-icon cream">${I('building')}</div><h3>Start with your first property</h3><p>Add properties and figures whenever you're ready. Nothing is prefilled with personal information.</p>${cta('Add your first property','newProperty')}</div>`}</div><div class="section-top"><h2>Portfolio outlook</h2><span class="tag gray">Estimates</span></div><div class="metric-grid">${metric('ESTIMATED EQUITY',money(s.equity),'Value less debt','trend')}${metric('PORTFOLIO LTV',s.value?s.ltv.toFixed(1)+'%':'—','Loan to value','chart','blue')}${metric('MORTGAGE COVERAGE',`${s.vals.filter(x=>x.m.estimated).length}/${s.vals.length}`,'Projection-ready','calendar','purple')}${metric('EXPENSES THIS MONTH',money(s.expense),'Recorded expenses only','wallet','cream')}</div><div class="section-top"><h2>Recent transactions</h2><button class="light-btn mini-btn" data-action="newTransaction">${I('plus')} Add transaction</button></div><div class="card">${transactionsTable(property.transactions.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,8))}</div><div class="section-top"><h2>Tools & records</h2></div><div class="card"><p class="brief-note">Market value uses your own baseline plus an optional growth assumption; it is not a live property valuation. Mortgage projections assume your entered interest rate and payments remain unchanged.</p><div class="action-area"><a class="outline-btn" href="https://landregistry.data.gov.uk/app/ukhpi" target="_blank" rel="noopener noreferrer">${I('external')} UK House Price Index</a><a class="outline-btn" href="https://www.gov.uk/search-house-prices" target="_blank" rel="noopener noreferrer">${I('external')} Sold prices</a></div><p class="insight-note">Cash flow = scheduled rent − mortgage payments − expenses recorded this month; it excludes tax, vacancies and unrecorded costs.</p></div>`}
function transactionsTable(ts){if(!ts.length)return `<div class="empty-state"><div class="round-icon">${I('wallet')}</div><h3>No transactions recorded</h3><p>Track rent and property spending as they occur.</p></div>`;return `<div class="scroll-x"><table class="data-table"><thead><tr><th>Date</th><th>Category / Property</th><th>Amount</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td class="nowrap">${E(formatDate(t.date,{day:'numeric',month:'short'}))}</td><td><strong>${E(t.category)}</strong><div class="item-meta">${E(property.properties.find(x=>x.id===t.propertyId)?.name||'Removed property')}${t.note?' · '+E(t.note):''}</div></td><td style="color:${t.type==='income'?'#26845c':'#bc6b57'}" class="nowrap">${t.type==='income'?'+':'−'}${money(t.amount)}</td><td><button class="icon-btn mini-btn" data-action="deleteTransaction" data-id="${E(t.id)}" aria-label="Delete transaction" style="width:32px;height:32px">${I('trash')}</button></td></tr>`).join('')}</tbody></table></div>`}
function propertyDetail(p,s){const m=mortgageEstimate(p),v=valueEstimate(p),model=p.model||{},tx=property.transactions.filter(t=>t.propertyId===p.id).sort((a,b)=>b.date.localeCompare(a.date));const expiry=model.fixedEnd?formatDate(model.fixedEnd):'Not set';return `<div class="page-intro"><div><button class="text-btn" data-action="backProperty">${I('chevronL')} All properties</button><span class="eyebrow">YOUR PROPERTY</span><h1>${E(p.name)}</h1><p>Recorded figures, estimated equity and activity.</p></div><button class="outline-btn" data-action="editProperty" data-id="${E(p.id)}">${I('edit')} Edit</button></div><div class="metric-grid">${metric('VALUE',money(v.value),v.estimated?'Projected':'Recorded baseline','house','cream')}${metric('MORTGAGE',money(m.balance),m.estimated?'Projected':'Recorded balance','wallet','blue')}${metric('EQUITY',money(v.value-m.balance),'Estimated','trend')}${metric('LTV',v.value?(m.balance/v.value*100).toFixed(1)+'%':'—','Loan to value','chart','purple')}</div><div class="split-grid spacer-top"><div class="card"><div class="small-row"><h3>Mortgage & valuation</h3><button class="light-btn mini-btn" data-action="propertyModel" data-id="${E(p.id)}">${I('edit')} Edit projections</button></div><div class="home-line"><span class="brief-note">Monthly mortgage payment</span><strong>${money(p.payment)}</strong></div><div class="home-line"><span class="brief-note">Monthly rent</span><strong>${money(p.rent)}</strong></div><div class="home-line"><span class="brief-note">Regular overpayment</span><strong>${money(model.overpayment)}</strong></div><div class="home-line"><span class="brief-note">Fixed rate ends</span><strong>${E(expiry)}</strong></div><p class="insight-note" style="margin-top:16px">Your projections are indicative, not lender-confirmed balances or property valuations.</p></div><div class="card"><h3>Connected Life Admin</h3><p class="brief-note">When something needs chasing — tenant correspondence, a bill, an insurance claim — create an admin case linked to this property.</p><button class="action-btn" data-action="propertyToCase" data-id="${E(p.id)}">${I('plus')} New admin case</button><div class="divider"></div><button class="danger-btn mini-btn" data-action="deleteProperty" data-id="${E(p.id)}">${I('trash')} Delete property</button></div></div><div class="section-top"><h2>Transactions</h2><button class="light-btn mini-btn" data-action="newTransaction" data-id="${E(p.id)}">${I('plus')} Add transaction</button></div><div class="card">${transactionsTable(tx)}</div>`}
// DISCIPLINE: defaults to month view, users can explore week / 6-month / year.
function dayChecks(d){const v=app.checks[d];return v&&typeof v==='object'?v:{}}
function checkCount(d){const values=dayChecks(d);return app.habits.reduce((n,h)=>n+(values[h.id]?1:0),0)}
function monthDays(d){const first=startMonth(d),start=weekStart(first),last=new Date(d.getFullYear(),d.getMonth()+1,0,12),count=Math.ceil(((last-start)/864e5+1)/7)*7;return Array.from({length:Math.max(35,count)},(_,i)=>addDays(start,i))}
function disciplineView(){const anchor=ui.calendarAnchor,view=ui.calendarView,selected=ui.selectedDate;let dates=Object.keys(app.checks).filter(d=>d.startsWith(today().slice(0,7))),monthTicks=dates.reduce((n,d)=>n+checkCount(d),0),activeDays=dates.filter(d=>checkCount(d)>0).length;let todayN=checkCount(today());const title=view==='week'?`Week of ${formatDate(iso(weekStart(parseDate(selected)||new Date())),{day:'numeric',month:'short',year:'numeric'})}`:view==='year'?String(anchor.getFullYear()):view==='six'?`${new Intl.DateTimeFormat('en-GB',{month:'short',year:'numeric'}).format(anchor)} — ${new Intl.DateTimeFormat('en-GB',{month:'short',year:'numeric'}).format(shiftMonth(anchor,5))}`:new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric'}).format(anchor);return `<div class="page-intro"><div><span class="eyebrow">DISCIPLINE CALENDAR</span><h1>Show up. Repeat.</h1><p>Your own daily habits, without the noise. Every tick counts.</p></div><button class="outline-btn" data-action="manageHabits">${I('settings')} Habits</button></div><div class="metric-grid">${metric('TODAY',`${todayN}/${app.habits.length}`,'Habits completed','checkCircle')}${metric('THIS MONTH',String(monthTicks),'Total check-ins','fire','cream')}${metric('ACTIVE DAYS',String(activeDays),'Days with at least one tick','calendar','blue')}${metric('HABITS',String(app.habits.length),'All fully editable','list','purple')}</div><div class="card spacer-top"><div class="calendar-toolbar"><div class="calendar-nav"><button class="icon-btn" data-action="prevPeriod" aria-label="Previous period">${I('chevronL')}</button><button class="icon-btn" data-action="nextPeriod" aria-label="Next period">${I('chevronR')}</button><button class="text-btn" data-action="todayCalendar">Today</button></div><div class="month-title">${E(title)}</div></div><div class="segmented" role="group" aria-label="Calendar zoom">${[['week','Week'],['month','Month'],['six','6 Months'],['year','Year']].map(([key,l])=>`<button data-action="calendarView" data-value="${key}" class="${view===key?'selected':''}">${l}</button>`).join('')}</div><div class="divider"></div>${view==='month'||view==='week'?calendarLarge(view==='month'?monthDays(anchor):Array.from({length:7},(_,i)=>addDays(weekStart(parseDate(selected)||new Date()),i)),anchor):calendarOverview(view,anchor)}</div>${view==='month'||view==='week'?disciplineDayPanel(selected):`<div class="info-pop spacer-top">Tap a day in the mini calendars to open its month and mark the habits you completed.</div>`}<div class="section-top"><h2>Make it yours</h2><button class="light-btn mini-btn" data-action="addHabit">${I('plus')} Add habit</button></div><div class="card"><p class="brief-note" style="margin-bottom:17px">Add, rename or remove habits at any time. Your calendar keeps going indefinitely, and your month view always opens first.</p><div class="pill-row">${app.habits.map(h=>`<span class="tag gray" style="gap:8px"><span class="dot" style="background:${E(h.color||'#399575')}"></span>${E(h.name)}</span>`).join('')||'<span class="muted">No habits yet</span>'}</div></div>`}
function calendarLarge(days,anchor){return `<div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="week-label">${d}</div>`).join('')}${days.map(d=>{let date=iso(d),n=checkCount(date),isToday=date===today(),isSel=date===ui.selectedDate,outside=d.getMonth()!==anchor.getMonth()&&ui.calendarView==='month';return `<button class="cal-day ${isToday?'today':''} ${isSel?'selected':''} ${outside?'outside':''}" data-action="selectDay" data-date="${date}" aria-label="${E(formatDate(date))}: ${n} habits completed"><span class="cal-number">${d.getDate()}</span><span class="day-dots">${app.habits.slice(0,8).map(h=>`<b class="${dayChecks(date)[h.id]?'':'missed'}"></b>`).join('')}</span>${n?`<span class="day-count">${n}/${app.habits.length}</span>`:'<span></span>'}</button>`}).join('')}</div>`}
function disciplineDayPanel(date){return `<section class="habit-day-panel"><div class="small-row"><div><span class="eyebrow" style="margin:0 0 6px">DAY DETAIL</span><h3 style="margin:0">${E(formatDate(date,{weekday:'long',day:'numeric',month:'long'}))}</h3></div><span class="tag">${checkCount(date)}/${app.habits.length} done</span></div><div class="divider"></div>${app.habits.length?app.habits.map(h=>{let checked=!!dayChecks(date)[h.id];return `<div class="habit-row"><span class="round-icon" style="background:${E(h.color||'#24825e')}1c;color:${E(h.color||'#24825e')};height:34px;width:34px;border-radius:11px">${I('checkCircle')}</span><span class="habit-name">${E(h.name)}</span><button class="habit-toggle ${checked?'active':''}" data-action="toggleHabit" data-date="${date}" data-id="${E(h.id)}" aria-label="${checked?'Uncheck':'Check'} ${E(h.name)} for ${E(date)}" aria-pressed="${checked}">${I(checked?'check':'plus')}</button></div>`}).join(''):`<div class="empty-state"><h3>Add your first habit</h3><p>Your calendar is ready whenever you are.</p><button class="action-btn" data-action="addHabit">${I('plus')} Add habit</button></div>`}</section>`}
function miniMonth(d){const days=monthDays(d),name=new Intl.DateTimeFormat('en-GB',{month:'short',year:'numeric'}).format(d);return `<div class="mini-month"><h3>${E(name)}</h3><div class="mini-days">${days.map(day=>{const same=day.getMonth()===d.getMonth(),date=iso(day),n=checkCount(date),lv=app.habits.length?Math.ceil(n/app.habits.length*4):0;return same?`<button class="mini-day level${lv}" data-action="miniSelectDay" data-date="${date}" title="${E(formatDate(date))} · ${n}/${app.habits.length} habits" aria-label="${E(formatDate(date))}, ${n} completed"></button>`:'<span class="mini-day blank"></span>'}).join('')}</div></div>`}
function calendarOverview(view,anchor){const start=view==='year'?new Date(anchor.getFullYear(),0,1,12):startMonth(anchor),amount=view==='year'?12:6;return `<div class="heatmap-grid">${Array.from({length:amount},(_,i)=>miniMonth(shiftMonth(start,i))).join('')}</div>`}
// LIFE ADMIN: simple, calm case management. Stored locally, not synced to any external organisation.
const caseStatuses={action:'Action required',waiting:'Waiting for reply',scheduled:'Scheduled',resolved:'Resolved'};
const caseCategories=['Banking','Property','Utilities','Vehicle','Government','Insurance','Subscriptions','Work','Other'];
const caseTag=s=>s==='action'?'red':s==='waiting'?'amber':s==='scheduled'?'blue':'gray';
function adminView(){if(ui.caseId){const c=app.cases.find(c=>c.id===ui.caseId);if(c)return caseDetail(c);ui.caseId=null}const todo=app.cases.filter(c=>c.status==='action').length,waiting=app.cases.filter(c=>c.status==='waiting').length,resolved=app.cases.filter(c=>c.status==='resolved').length;let items=app.cases.filter(c=>ui.caseFilter==='active'?c.status!=='resolved':ui.caseFilter==='all'?true:c.status===ui.caseFilter).sort((a,b)=>{if(a.status==='resolved'&&b.status!=='resolved')return 1;if(b.status==='resolved'&&a.status!=='resolved')return -1;return String(a.due||'9999').localeCompare(String(b.due||'9999'))});return `<div class="page-intro"><div><span class="eyebrow">LIFE ADMIN</span><h1>Clear your mind.</h1><p>One reliable home for open cases, follow-ups and documents.</p></div>${cta('New case','newCase')}</div><div class="case-stats">${metric('TO ACT',String(todo),'Need attention','bell','rose')}${metric('WAITING',String(waiting),'With someone else','clock','cream')}${metric('RESOLVED',String(resolved),'Peace of mind','checkCircle')}</div><div class="section-top"><h2>Your cases</h2><span class="muted-label">${items.length} SHOWING</span></div><div class="case-filter-row">${[['active','Active'],['action','To do'],['waiting','Waiting'],['scheduled','Scheduled'],['resolved','Archive'],['all','All']].map(([key,label])=>`<button class="filter-chip ${ui.caseFilter===key?'active':''}" data-action="caseFilter" data-value="${key}">${label}</button>`).join('')}</div><div class="item-list">${items.length?items.map(c=>caseCard(c)).join(''):`<div class="card empty-state"><div class="round-icon purple">${I('folder')}</div><h3>${ui.caseFilter==='active'?'Everything is under control.':'No cases in this section'}</h3><p>New issues can be captured in seconds, then filed until they need you again.</p>${ui.caseFilter==='active'?cta('Create a case','newCase'):''}</div>`}</div><div class="section-top"><h2>How this helps</h2></div><div class="card"><div class="home-line"><div><strong class="item-title">Action required</strong><div class="line-sub">Only the things you can act on now</div></div><span class="tag red">To do</span></div><div class="home-line"><div><strong class="item-title">Waiting room</strong><div class="line-sub">Set a follow-up date and get it off your mind</div></div><span class="tag amber">Waiting</span></div><div class="home-line"><div><strong class="item-title">Resolved archive</strong><div class="line-sub">Keep the complete history without clutter</div></div><span class="tag gray">Done</span></div></div>`}
function caseCard(c){const linked=property.properties.find(p=>p.id===c.propertyId),overdue=c.due&&c.due<today()&&c.status!=='resolved';return `<button class="item-card" style="width:100%;text-align:left" data-action="openCase" data-id="${E(c.id)}"><div class="small-row"><span class="tag ${caseTag(c.status)}">${E(caseStatuses[c.status]||'Open')}</span>${c.due?`<span class="tag ${overdue?'red':'gray'}">${overdue?'Overdue · ':''}${E(formatDate(c.due,{day:'numeric',month:'short'}))}</span>`:I('chevronR')}</div><div class="item-title" style="margin-top:12px">${E(c.title)}</div><div class="item-meta">${E(c.category||'Other')}${linked?' · '+E(linked.name):''}</div>${c.nextAction?`<p class="brief-note" style="margin:13px 0 0">${I('arrow')} ${E(c.nextAction)}</p>`:''}</button>`}
function caseDetail(c){const prop=property.properties.find(p=>p.id===c.propertyId),logs=Array.isArray(c.history)?[...c.history].reverse():[];return `<div class="case-detail"><div class="page-intro"><div><button class="text-btn" data-action="backCases">${I('chevronL')} All cases</button><span class="eyebrow">${E(c.category||'LIFE ADMIN')}</span><h1>${E(c.title)}</h1><div class="pill-row"><span class="tag ${caseTag(c.status)}">${E(caseStatuses[c.status]||'Active')}</span>${prop?`<button class="text-btn mini-btn" data-action="caseToProperty" data-id="${E(prop.id)}">${I('link')} ${E(prop.name)}</button>`:''}</div></div><button class="outline-btn" data-action="editCase" data-id="${E(c.id)}">${I('edit')} Edit case</button></div><div class="split-grid"><div><div class="card case-banner"><span class="muted-label">YOUR NEXT ACTION</span><h3>${E(c.nextAction||'No next action set')}</h3><p>${c.due?'Follow up: '+E(formatDate(c.due)):'Add a follow-up date whenever useful.'}</p><div class="action-area"><button class="light-btn mini-btn" data-action="editCase" data-id="${E(c.id)}">${I('edit')} Update</button>${c.due?`<button class="outline-btn mini-btn" data-action="exportIcs" data-id="${E(c.id)}">${I('calendar')} Add to calendar</button>`:''}</div></div><div class="section-top"><h2>Case timeline</h2><button class="light-btn mini-btn" data-action="addCaseUpdate" data-id="${E(c.id)}">${I('plus')} Add update</button></div><div class="card">${logs.length?logs.map((h,i)=>`<div class="timeline-entry"><div class="timeline-rail"><span class="timeline-dot">${I('note')}</span>${i<logs.length-1?'<span class="timeline-line"></span>':''}</div><div class="timeline-content"><strong>${E(h.title||'Update')}</strong><p>${E(h.body||'')}</p><small>${E(formatDate((h.date||'').slice(0,10)))}</small></div></div>`).join(''):`<div class="empty-state"><h3>No updates yet</h3><p>Add a note after a call, email or decision. You'll always know what happened.</p></div>`}</div></div><div><div class="card"><h3>Case information</h3><div class="home-line"><span class="brief-note">Status</span><strong>${E(caseStatuses[c.status]||'Open')}</strong></div><div class="home-line"><span class="brief-note">Organisation</span><strong>${E(c.organisation||'—')}</strong></div><div class="home-line"><span class="brief-note">Reference</span><strong style="overflow-wrap:anywhere">${E(c.reference||'—')}</strong></div><div class="home-line"><span class="brief-note">Due / follow-up</span><strong>${c.due?E(formatDate(c.due)):'—'}</strong></div><div class="home-line"><span class="brief-note">Property</span><strong>${E(prop?.name||'None linked')}</strong></div>${c.description?`<div class="divider"></div><h3>Background</h3><p class="brief-note">${E(c.description)}</p>`:''}<div class="action-area">${c.status!=='resolved'?`<button class="action-btn mini-btn" data-action="markCaseResolved" data-id="${E(c.id)}">${I('check')} Resolve</button>`:`<button class="light-btn mini-btn" data-action="reopenCase" data-id="${E(c.id)}">${I('rotate')} Reopen</button>`}<button class="danger-btn mini-btn" data-action="deleteCase" data-id="${E(c.id)}">${I('trash')} Delete</button></div></div><div class="card spacer-top"><div class="small-row"><h3 style="margin:0">Documents</h3><button class="light-btn mini-btn" data-action="attachDoc" data-id="${E(c.id)}">${I('paperclip')} Attach</button></div><p class="brief-note" style="margin:10px 0">Store small letters, screenshots and PDFs with this case on this device.</p><div id="attachmentList"><span class="muted">Loading attachments…</span></div><p class="insight-note" style="margin-top:12px">Files live in your browser's local storage and are included when you export an AMP backup.</p></div></div></div></div>`}
// GOALS: fully user-created journeys. Every checkpoint carries equal weight.
function goalProgress(g){return percent((g.steps||[]).filter(s=>s.done).length,(g.steps||[]).length)}
function goalsView(){if(ui.goalId){const g=app.goals.find(g=>g.id===ui.goalId);if(g)return goalDetail(g);ui.goalId=null}const goals=app.goals.filter(g=>ui.goalTab==='archived'?g.archived:!g.archived);const active=app.goals.filter(g=>!g.archived),done=active.filter(g=>g.steps.length&&g.steps.every(s=>s.done)).length;return `<div class="page-intro"><div><span class="eyebrow">GOALS & CHECKPOINTS</span><h1>Your journey, your rules.</h1><p>Set the destination. Create the checkpoints. Feel the progress.</p></div>${cta('New goal','newGoal')}</div><div class="metric-grid">${metric('ACTIVE GOALS',String(active.length),'Made by you','target')}${metric('COMPLETED',String(done),'Finished journeys','trophy','cream')}${metric('CHECKPOINTS DONE',String(active.reduce((n,g)=>n+g.steps.filter(s=>s.done).length,0)),'Across active goals','checkCircle','blue')}${metric('LEFT TO GO',String(active.reduce((n,g)=>n+g.steps.filter(s=>!s.done).length,0)),'Upcoming checkpoints','flag','purple')}</div><div class="section-top"><h2>My journeys</h2><div class="segmented"><button data-action="goalTab" data-value="journey" class="${ui.goalTab==='journey'?'selected':''}">Active</button><button data-action="goalTab" data-value="archived" class="${ui.goalTab==='archived'?'selected':''}">Archive</button></div></div>${goals.length?`<div class="goal-grid">${goals.map(g=>`<button class="goal-card" data-action="openGoal" data-id="${E(g.id)}"><div class="small-row"><span class="round-icon ${g.related==='property'?'cream':g.related==='discipline'?'blue':g.related==='admin'?'purple':''}">${I(g.related==='property'?'building':g.related==='discipline'?'calendarCheck':g.related==='admin'?'folder':'target')}</span>${I('upRight')}</div><h3>${E(g.name)}</h3><div class="small-row"><small>${g.steps.filter(s=>s.done).length} of ${g.steps.length} checkpoints</small><strong style="font-size:16px">${goalProgress(g)}%</strong></div><div class="bar spacer-top"><div class="bar-fill" style="width:${goalProgress(g)}%"></div></div>${g.due?`<p class="item-meta" style="margin:13px 0 0">Target ${E(formatDate(g.due))}</p>`:''}</button>`).join('')}</div>`:`<div class="card empty-state"><div class="round-icon rose">${I('target')}</div><h3>${ui.goalTab==='archived'?'No archived journeys':'An empty canvas, just for you.'}</h3><p>${ui.goalTab==='archived'?'Finished and archived goals will live here.':'No suggested goals or rules. Create anything you want to work toward and break it into steps.'}</p>${ui.goalTab==='archived'?'':cta('Create your first goal','newGoal')}</div>`}<div class="section-top"><h2>How it works</h2></div><div class="card"><div class="home-line"><div><strong>01. Create a goal</strong><div class="line-sub">Give your journey a name</div></div>${I('target')}</div><div class="home-line"><div><strong>02. Place your checkpoints</strong><div class="line-sub">Add as many milestones as you need, in your own order</div></div>${I('flag')}</div><div class="home-line"><div><strong>03. Complete each step</strong><div class="line-sub">Your progress bar animates automatically to 100%</div></div>${I('sparkle')}</div></div>`}
function goalDetail(g){const p=goalProgress(g),complete=g.steps.filter(s=>s.done).length;return `<div><button class="text-btn" data-action="backGoals">${I('chevronL')} All journeys</button><div class="goal-detail-header"><span class="eyebrow" style="color:#bfe6cd">YOUR PERSONAL JOURNEY</span><div class="small-row" style="align-items:flex-start"><div><h1 style="font-size:clamp(27px,4vw,43px);margin:3px 0 12px">${E(g.name)}</h1><p style="margin:0">${E(g.description||'One checkpoint at a time.')}</p></div>${I(p===100?'trophy':'target')}</div><div class="small-row" style="margin-top:28px;align-items:end"><div><div class="goal-percentage" aria-label="${p} percent complete">${p}%</div><span style="font-size:12px;color:#c3e4d2">${complete} of ${g.steps.length} checkpoints completed</span></div>${g.due?`<span class="tag gray">Target: ${E(formatDate(g.due))}</span>`:''}</div><div class="bar large" style="margin-top:15px"><div class="bar-fill" style="width:${p}%"></div></div>${p===100&&g.steps.length?`<div class="finished-banner">${I('trophy')} You completed this journey. Beautiful work.</div>`:''}</div><div class="section-top"><div><h2>Your checkpoints</h2><p class="brief-note" style="margin:6px 0 0">Tap a circle or step to mark it done. Each step is worth ${g.steps.length?Math.round(100/g.steps.length*10)/10:0}%.</p></div><button class="light-btn mini-btn" data-action="newStep" data-id="${E(g.id)}">${I('plus')} Add step</button></div><div class="card">${g.steps.length?`<div class="checkpoint-list">${g.steps.map((s,i)=>`<div class="checkpoint"><div class="checkpoint-rail"><button class="checkpoint-node ${s.done?'done':''}" data-action="toggleStep" data-id="${E(g.id)}" data-step="${E(s.id)}" aria-label="${s.done?'Undo':'Complete'} checkpoint ${E(s.name)}" aria-pressed="${!!s.done}">${s.done?I('check'):i+1}</button>${i<g.steps.length-1?`<span class="checkpoint-track ${s.done?'done':''}"></span>`:''}</div><div class="checkpoint-content"><button class="checkpoint-main ${s.done?'done':''}" data-action="toggleStep" data-id="${E(g.id)}" data-step="${E(s.id)}"><strong>${E(s.name)}</strong><small>${s.done?'Completed':s.due?'Target '+E(formatDate(s.due)):'Tap to complete'}${s.note?' · '+E(s.note):''}</small></button><div class="checkpoint-actions"><button data-action="moveStep" data-id="${E(g.id)}" data-step="${E(s.id)}" data-dir="-1" ${i===0?'disabled':''} aria-label="Move up">${I('moveUp')}</button><button data-action="moveStep" data-id="${E(g.id)}" data-step="${E(s.id)}" data-dir="1" ${i===g.steps.length-1?'disabled':''} aria-label="Move down">${I('moveDown')}</button><button data-action="editStep" data-id="${E(g.id)}" data-step="${E(s.id)}" aria-label="Edit checkpoint">${I('edit')}</button><button data-action="deleteStep" data-id="${E(g.id)}" data-step="${E(s.id)}" aria-label="Delete checkpoint">${I('trash')}</button></div></div></div>`).join('')}</div>`:`<div class="empty-state"><div class="round-icon rose">${I('flag')}</div><h3>Build your journey</h3><p>Add the first step. More checkpoints can always be added, moved, renamed or removed.</p><button class="action-btn" data-action="newStep" data-id="${E(g.id)}">${I('plus')} Add first checkpoint</button></div>`}</div><div class="section-top"><h2>Journey settings</h2></div><div class="card"><div class="action-area"><button class="outline-btn mini-btn" data-action="editGoal" data-id="${E(g.id)}">${I('edit')} Edit goal</button>${g.related&&g.related!=='none'?`<button class="light-btn mini-btn" data-page="${E(g.related)}">${I('link')} Open ${E(pageNames[g.related]||'related app')}</button>`:''}<button class="outline-btn mini-btn" data-action="archiveGoal" data-id="${E(g.id)}">${I('archive')} ${g.archived?'Restore':'Archive'}</button><button class="danger-btn mini-btn" data-action="deleteGoal" data-id="${E(g.id)}">${I('trash')} Delete</button></div><p class="insight-note">Progress is simply completed checkpoints ÷ total checkpoints. Adding or removing checkpoints recalculates it automatically.</p></div></div>`}
// FORMS AND INTERACTIONS
const field=(label,name,type='text',val='',opts='')=>`<label class="form-field">${E(label)}<input name="${name}" type="${type}" value="${E(val??'')}" ${opts}></label>`;
const area=(label,name,val='')=>`<label class="form-field wide">${E(label)}<textarea name="${name}" maxlength="1200">${E(val||'')}</textarea></label>`;
const choose=(label,name,items,val='')=>`<label class="form-field">${E(label)}<select name="${name}">${items.map(it=>{let [value,text]=Array.isArray(it)?it:[it,it];return `<option value="${E(value)}" ${String(value)===String(val)?'selected':''}>${E(text)}</option>`}).join('')}</select></label>`;
function modalForm(kind,payload={}){let title='',body='',submit='Save',form=true;const g=app.goals.find(g=>g.id===payload.id),c=app.cases.find(c=>c.id===payload.id),p=property.properties.find(p=>p.id===payload.id);const step=g?.steps.find(s=>s.id===payload.step);switch(kind){
case 'goal':title=g?'Edit your goal':'Create a goal';body=`<div class="form-grid"><div class="form-field wide">${field('Goal name','name','text',g?.name||'','required maxlength="100"')}</div>${area('Description (optional)','description',g?.description)}${field('Target date (optional)','due','date',g?.due||'')}${choose('Connected AMP app (optional)','related',[['none','None'],['property','Property'],['discipline','Discipline'],['admin','Life Admin']],g?.related||'none')}</div>`;submit=g?'Save changes':'Create journey';break;
case 'step':title=step?'Edit checkpoint':'New checkpoint';body=`<div class="form-grid"><div class="form-field wide">${field('Checkpoint name','name','text',step?.name||'','required maxlength="130"')}</div>${field('Target date (optional)','due','date',step?.due||'')}<div></div>${area('Short note (optional)','note',step?.note)}</div>`;submit=step?'Save checkpoint':'Add checkpoint';break;
case 'habit':{const h=app.habits.find(h=>h.id===payload.id);title=h?'Edit habit':'Add habit';body=`<div class="form-grid"><div class="form-field wide">${field('Habit name','name','text',h?.name||'','required maxlength="60"')}</div>${choose('Accent colour','color',[['#32835f','Evergreen'],['#6d9bd8','Sky blue'],['#ad8bd0','Lavender'],['#d4a667','Sunshine'],['#d4838c','Rose']],h?.color||'#32835f')}</div>`;submit=h?'Save habit':'Add habit';break}
case 'habits':title='Manage your habits';form=false;body=`<p class="brief-note">Choose only the habits that matter to you. Renaming or removing a habit is entirely up to you.</p><div class="item-list">${app.habits.map(h=>`<div class="item-card small-row"><div class="text-icon"><span class="dot" style="background:${E(h.color||'#32835f')}"></span><strong>${E(h.name)}</strong></div><div class="pill-row"><button class="icon-btn mini-btn" data-action="editHabit" data-id="${E(h.id)}" aria-label="Edit ${E(h.name)}">${I('edit')}</button><button class="icon-btn mini-btn" data-action="deleteHabit" data-id="${E(h.id)}" aria-label="Delete ${E(h.name)}">${I('trash')}</button></div></div>`).join('')}</div><div class="action-area"><button class="action-btn" data-action="addHabit">${I('plus')} Add habit</button></div>`;break;
case 'property':title=p?'Edit property':'New property';body=`<div class="form-grid"><div class="form-field wide">${field('Property nickname','name','text',p?.name||'','required maxlength="70"')}</div>${field('Estimated value (£)','value','number',p?.value??'','required min="0" step="0.01"')}${field('Outstanding mortgage (£)','mortgage','number',p?.mortgage??'','required min="0" step="0.01"')}${field('Monthly rent (£)','rent','number',p?.rent??'','required min="0" step="0.01"')}${field('Monthly mortgage payment (£)','payment','number',p?.payment??'','required min="0" step="0.01"')}</div>`;submit=p?'Save property':'Add property';break;
case 'model':{title='Mortgage & valuation settings';let m=p?.model||{};body=`<p class="brief-note">Optional inputs. These projections are mathematical estimates, not live lender or valuation data.</p><div class="form-grid">${field('Mortgage balance on reference date (£)','baseBalance','number',m.baseBalance??'','min="0" step="0.01"')}${field('Balance reference date','baseDate','date',m.baseDate||'')}${field('Annual interest rate (%)','rate','number',m.rate??'','min="0" max="100" step="0.001"')}${field('Regular monthly repayment (£)','monthlyPayment','number',m.monthlyPayment??p?.payment??'','min="0" step="0.01"')}${field('Monthly overpayment (£)','overpayment','number',m.overpayment??'','min="0" step="0.01"')}${field('Fixed-rate expiry','fixedEnd','date',m.fixedEnd||'')}${field('Property value baseline (£)','baseValue','number',m.baseValue??p?.value??'','min="0" step="0.01"')}${field('Valuation baseline date','valueDate','date',m.valueDate||'')}${field('Assumed annual growth (%)','growth','number',m.growth??'','min="-50" max="50" step="0.1"')}${choose('Property type','propertyType',[['','Not specified'],['detached','Detached'],['semi-detached','Semi-detached'],['terraced','Terraced'],['flat','Flat / maisonette']],m.propertyType||'')}</div>`;submit='Save projections';break}
case 'transaction':title='Add transaction';body=`<div class="form-grid">${choose('Property','propertyId',property.properties.map(p=>[p.id,p.name]),payload.id||property.properties[0]?.id||'')}${choose('Type','type',[['income','Income'],['expense','Expense']])}${choose('Category','category',['Rent received','Maintenance','Insurance','Council tax','Service charges','Utilities','Other'])}${field('Amount (£)','amount','number','','required min="0.01" step="0.01"')}${field('Date','date','date',today(),'required')}${field('Note','note','text','','maxlength="120"')}</div>`;submit='Add transaction';break;
case 'case':{title=c?'Edit case':'Create an admin case';let options=[['','None'],...property.properties.map(p=>[p.id,p.name])];body=`<div class="form-grid"><div class="form-field wide">${field('Case title','title','text',c?.title||'','required maxlength="100"')}</div>${choose('Category','category',caseCategories,c?.category||'Other')}${choose('Status','status',Object.entries(caseStatuses),c?.status||'action')}${field('Organisation / contact','organisation','text',c?.organisation||'','maxlength="100"')}${field('Reference (optional)','reference','text',c?.reference||'','maxlength="100"')}${field('Next action','nextAction','text',c?.nextAction||'','maxlength="170"')}${field('Follow-up / deadline','due','date',c?.due||'')}${choose('Related property','propertyId',options,c?.propertyId||payload.propertyId||'')}${area('Background (optional)','description',c?.description)}</div>`;submit=c?'Save case':'Create case';break}
case 'update':title='Add case update';body=`<div class="form-grid"><div class="form-field wide">${field('Update title','title','text','','required maxlength="100"')}</div>${area('What happened?','body','')}${field('Date','date','date',today(),'required')}</div>`;submit='Save update';break;
case 'backup':title='Backup & privacy';form=false;body=`<div class="private-caution">${I('lock')} Your data currently stays in this browser on this device. It is not encrypted in browser storage or synced across devices. Anyone who has access to this unlocked browser profile may be able to read it.</div><div class="action-area"><button class="action-btn" data-action="exportAll">${I('download')} Export everything</button><button class="outline-btn" data-action="importAll">${I('upload')} Import backup</button></div><p class="brief-note">Export includes your saved properties, transactions, habits, cases, goals and locally attached documents. Store the JSON file securely. An import replaces your current AMP data; check your backup before proceeding.</p><div class="divider"></div><button class="danger-btn" data-action="eraseAll">${I('trash')} Erase all AMP data on this device</button>`;break;
default:return}
ui.modal={kind,...payload};$('#modalContent').innerHTML=`<div class="modal-inside"><div class="modal-head"><h2>${E(title)}</h2><button class="modal-close" data-action="closeModal" aria-label="Close">${I('close')}</button></div>${form?`<form id="modalForm" data-form="${E(kind)}">${body}<div class="form-actions"><button class="outline-btn" type="button" data-action="closeModal">Cancel</button><button class="action-btn" type="submit">${I('check')} ${E(submit)}</button></div></form>`:body}</div>`;const m=$('#modal');if(!m.open)m.showModal()}
function closeModal(){const m=$('#modal');if(m.open)m.close();ui.modal=null}
function handleSubmit(event){if(event.target.id!=='modalForm')return;event.preventDefault();const f=event.target,data=Object.fromEntries(new FormData(f).entries()),kind=ui.modal?.kind,id=ui.modal?.id;let message='Saved';switch(kind){
case 'goal':{const target=app.goals.find(g=>g.id===id);if(!data.name.trim())return;if(target){Object.assign(target,{name:data.name.trim().slice(0,100),description:data.description.slice(0,1200),due:data.due,related:data.related});message='Goal updated'}else{const g={id:uid(),name:data.name.trim().slice(0,100),description:data.description.slice(0,1200),due:data.due,related:data.related,archived:false,steps:[],createdAt:today()};app.goals.push(g);ui.goalId=g.id;message='Journey created'}break}
case 'step':{const g=app.goals.find(g=>g.id===id);if(!g||!data.name.trim())return;const s=g.steps.find(s=>s.id===ui.modal.step);if(s){Object.assign(s,{name:data.name.trim().slice(0,130),due:data.due,note:data.note.slice(0,1200)});message='Checkpoint updated'}else{g.steps.push({id:uid(),name:data.name.trim().slice(0,130),due:data.due,note:data.note.slice(0,1200),done:false});message='Checkpoint added'}break}
case 'habit':{if(!data.name.trim())return;const h=app.habits.find(h=>h.id===id);if(h){h.name=data.name.trim().slice(0,60);h.color=data.color}else app.habits.push({id:uid(),name:data.name.trim().slice(0,60),color:data.color});message='Habit saved';break}
case 'property':{if(!data.name.trim())return;const obj={name:data.name.trim().slice(0,70),value:num(data.value),mortgage:num(data.mortgage),rent:num(data.rent),payment:num(data.payment)};const p=property.properties.find(p=>p.id===id);if(p)Object.assign(p,obj);else property.properties.push({id:uid(),...obj});message='Property saved';break}
case 'model':{const p=property.properties.find(p=>p.id===id);if(!p)return;p.model=data;message='Projection settings saved';break}
case 'transaction':{if(!property.properties.some(p=>p.id===data.propertyId))return toast('Add a property first');property.transactions.push({id:uid(),propertyId:data.propertyId,type:data.type,category:data.category,amount:num(data.amount),date:data.date,note:(data.note||'').slice(0,120)});message='Transaction added';break}
case 'case':{if(!data.title.trim())return;const obj={title:data.title.trim().slice(0,100),category:data.category,status:data.status,organisation:data.organisation.slice(0,100),reference:data.reference.slice(0,100),nextAction:data.nextAction.slice(0,170),due:data.due,propertyId:data.propertyId,description:data.description.slice(0,1200)};const c=app.cases.find(c=>c.id===id);if(c){const prev=c.status;Object.assign(c,obj);if(prev!==c.status){c.history??=[];c.history.push({date:today(),title:'Status changed',body:caseStatuses[c.status]})}message='Case updated'}else{const c={id:uid(),...obj,history:[{date:today(),title:'Case created',body:'New case opened'}]};app.cases.push(c);ui.caseId=c.id;ui.page='admin';message='Case created'}break}
case 'update':{const c=app.cases.find(c=>c.id===id);if(!c)return;c.history??=[];c.history.push({date:data.date||today(),title:data.title.trim().slice(0,100),body:data.body.slice(0,1200)});message='Update recorded';break}
default:return}
if(save()){closeModal();render();toast(message)}}
function mutateAndRender(msg){save();render();if(msg)toast(msg)}
function handleAction(event){const nav=event.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}const b=event.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id,stepId=b.dataset.step,dir=Number(b.dataset.dir||0);let g,c,p;switch(act){
case 'closeModal':closeModal();break;
case 'backup':modalForm('backup');break;
case 'newGoal':ui.goalId=null;modalForm('goal');break;
case 'editGoal':modalForm('goal',{id});break;
case 'openGoal':ui.goalId=id;ui.goalTab='journey';render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'backGoals':ui.goalId=null;render();break;
case 'goalTab':ui.goalTab=b.dataset.value;render();break;
case 'newStep':modalForm('step',{id});break;
case 'editStep':modalForm('step',{id,step:stepId});break;
case 'toggleStep':g=app.goals.find(g=>g.id===id);if(!g)return;{const s=g.steps.find(s=>s.id===stepId);if(!s)return;const old=goalProgress(g);s.done=!s.done;s.completedAt=s.done?new Date().toISOString():null;save();render();const bar=$('.goal-detail-header .bar-fill');if(bar){const target=goalProgress(g);bar.style.transition='none';bar.style.width=old+'%';requestAnimationFrame(()=>requestAnimationFrame(()=>{bar.style.transition='width .65s cubic-bezier(.2,.8,.2,1)';bar.style.width=target+'%'}))}if(goalProgress(g)===100&&g.steps.length)toast('Journey complete. Every step counted!');}break;
case 'deleteStep':g=app.goals.find(g=>g.id===id);if(g&&confirm('Remove this checkpoint from the journey?')){g.steps=g.steps.filter(s=>s.id!==stepId);mutateAndRender('Checkpoint removed')}break;
case 'moveStep':g=app.goals.find(g=>g.id===id);if(!g)return;{const i=g.steps.findIndex(s=>s.id===stepId),j=i+dir;if(i<0||j<0||j>=g.steps.length)return;[g.steps[i],g.steps[j]]=[g.steps[j],g.steps[i]];mutateAndRender();}break;
case 'archiveGoal':g=app.goals.find(g=>g.id===id);if(g){g.archived=!g.archived;ui.goalId=null;ui.goalTab=g.archived?'archived':'journey';mutateAndRender(g.archived?'Goal archived':'Goal restored')}break;
case 'deleteGoal':if(confirm('Delete this goal and all checkpoints? This cannot be undone.')){app.goals=app.goals.filter(g=>g.id!==id);ui.goalId=null;mutateAndRender('Goal deleted')}break;
case 'manageHabits':modalForm('habits');break;
case 'addHabit':modalForm('habit');break;
case 'editHabit':modalForm('habit',{id});break;
case 'deleteHabit':if(confirm('Remove this habit from your calendar? Its old checkmarks will no longer be shown.')){app.habits=app.habits.filter(h=>h.id!==id);Object.keys(app.checks).forEach(d=>{delete app.checks[d][id];if(!Object.keys(app.checks[d]).length)delete app.checks[d]});save();modalForm('habits');render();toast('Habit removed')}break;
case 'toggleHabit':{const date=b.dataset.date;const values={...dayChecks(date)};values[id]=!values[id];if(!values[id])delete values[id];if(Object.keys(values).length)app.checks[date]=values;else delete app.checks[date];mutateAndRender();}break;
case 'calendarView':ui.calendarView=b.dataset.value;if(ui.calendarView==='year')ui.calendarAnchor=new Date(ui.calendarAnchor.getFullYear(),0,1,12);else if(ui.calendarView==='month')ui.calendarAnchor=startMonth(parseDate(ui.selectedDate)||new Date());render();break;
case 'prevPeriod':case 'nextPeriod':{let n=act==='prevPeriod'?-1:1;if(ui.calendarView==='week'){ui.selectedDate=iso(addDays(parseDate(ui.selectedDate),n*7));ui.calendarAnchor=startMonth(parseDate(ui.selectedDate))}else if(ui.calendarView==='year')ui.calendarAnchor=new Date(ui.calendarAnchor.getFullYear()+n,0,1,12);else ui.calendarAnchor=shiftMonth(ui.calendarAnchor,n*(ui.calendarView==='six'?6:1));render();}break;
case 'todayCalendar':ui.selectedDate=today();ui.calendarAnchor=startMonth(new Date());render();break;
case 'selectDay':ui.selectedDate=b.dataset.date;if(ui.calendarView==='month')ui.calendarAnchor=startMonth(parseDate(ui.selectedDate));render();break;
case 'miniSelectDay':ui.selectedDate=b.dataset.date;ui.calendarAnchor=startMonth(parseDate(ui.selectedDate));ui.calendarView='month';render();break;
case 'newProperty':modalForm('property');break;
case 'openProperty':ui.propertyId=id;render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'backProperty':ui.propertyId=null;render();break;
case 'editProperty':modalForm('property',{id});break;
case 'propertyModel':modalForm('model',{id});break;
case 'newTransaction':if(!property.properties.length)return toast('Add a property first');modalForm('transaction',{id});break;
case 'deleteTransaction':if(confirm('Delete this transaction?')){property.transactions=property.transactions.filter(t=>t.id!==id);mutateAndRender('Transaction deleted')}break;
case 'deleteProperty':if(confirm('Delete this property and all its transactions? This cannot be undone.')){property.properties=property.properties.filter(p=>p.id!==id);property.transactions=property.transactions.filter(t=>t.propertyId!==id);app.cases.forEach(c=>{if(c.propertyId===id)c.propertyId=''});ui.propertyId=null;mutateAndRender('Property deleted')}break;
case 'propertyToCase':ui.page='admin';ui.caseId=null;render();modalForm('case',{propertyId:id});break;
case 'newCase':modalForm('case');break;
case 'editCase':modalForm('case',{id});break;
case 'openCase':ui.page='admin';ui.caseId=id;render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'backCases':ui.caseId=null;render();break;
case 'caseFilter':ui.caseFilter=b.dataset.value;render();break;
case 'caseToProperty':ui.page='property';ui.propertyId=id;ui.caseId=null;render();break;
case 'addCaseUpdate':modalForm('update',{id});break;
case 'markCaseResolved':case 'reopenCase':c=app.cases.find(c=>c.id===id);if(c){c.status=act==='markCaseResolved'?'resolved':'action';c.history??=[];c.history.push({date:today(),title:c.status==='resolved'?'Case resolved':'Case reopened',body:''});mutateAndRender(c.status==='resolved'?'Case resolved':'Case reopened')}break;
case 'deleteCase':if(confirm('Delete this case, its updates and attached files?')){app.cases=app.cases.filter(c=>c.id!==id);deleteCaseDocs(id).catch(()=>{});ui.caseId=null;mutateAndRender('Case deleted')}break;
case 'exportIcs':c=app.cases.find(c=>c.id===id);if(c&&c.due)downloadICS(c);break;
case 'attachDoc':attachDocuments(id);break;
case 'downloadDoc':downloadAttachment(id);break;
case 'deleteDoc':if(confirm('Remove this attached document?'))deleteAttachment(id);break;
case 'exportAll':exportAll();break;
case 'importAll':$('#importFile').click();break;
case 'eraseAll':if(confirm('Erase ALL AMP data (properties, habits, goals, admin cases and documents) from this browser? Export a backup first.')){if(confirm('Are you certain? This cannot be undone without a backup.')){app=freshApp();property={properties:[],transactions:[]};ui.page='home';ui.goalId=null;ui.caseId=null;ui.propertyId=null;clearDocs().catch(()=>{});save();closeModal();render();toast('AMP data erased')}}break;
}}
// Local IndexedDB document vault. All records remain on the user's device.
let dbPromise;
function openDB(){if(!('indexedDB' in window))return Promise.reject(new Error('Document storage unavailable'));if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{let req=indexedDB.open('amp-documents',1);req.onupgradeneeded=()=>{let s=req.result.createObjectStore('documents',{keyPath:'id'});s.createIndex('byCase','caseId',{unique:false})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function docsAll(){const db=await openDB();return new Promise((res,rej)=>{const req=db.transaction('documents','readonly').objectStore('documents').getAll();req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
async function docSave(d){const db=await openDB();return new Promise((res,rej)=>{const req=db.transaction('documents','readwrite').objectStore('documents').put(d);req.onsuccess=()=>res();req.onerror=()=>rej(req.error)})}
async function docGet(id){const db=await openDB();return new Promise((res,rej)=>{const req=db.transaction('documents','readonly').objectStore('documents').get(id);req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
async function docDelete(id){const db=await openDB();return new Promise((res,rej)=>{const req=db.transaction('documents','readwrite').objectStore('documents').delete(id);req.onsuccess=()=>res();req.onerror=()=>rej(req.error)})}
async function clearDocs(){const db=await openDB();return new Promise((res,rej)=>{const req=db.transaction('documents','readwrite').objectStore('documents').clear();req.onsuccess=()=>res();req.onerror=()=>rej(req.error)})}
async function deleteCaseDocs(caseId){for(const d of(await docsAll()).filter(x=>x.caseId===caseId))await docDelete(d.id)}
async function renderAttachments(caseId){const el=$('#attachmentList');if(!el)return;try{const docs=(await docsAll()).filter(x=>x.caseId===caseId);if(!$('#attachmentList')||ui.caseId!==caseId)return;$('#attachmentList').innerHTML=docs.length?docs.map(d=>`<div class="home-line"><div style="min-width:0"><strong class="item-title" style="overflow-wrap:anywhere">${E(d.name)}</strong><div class="line-sub">${(d.size/1024).toFixed(0)} KB · ${E(formatDate(d.date))}</div></div><div class="pill-row"><button class="icon-btn" style="width:34px;height:34px" data-action="downloadDoc" data-id="${E(d.id)}" aria-label="Download file">${I('download')}</button><button class="icon-btn" style="width:34px;height:34px" data-action="deleteDoc" data-id="${E(d.id)}" aria-label="Remove file">${I('trash')}</button></div></div>`).join(''):'<span class="muted" style="font-size:12px">No files attached yet.</span>'}catch(e){if($('#attachmentList'))$('#attachmentList').innerHTML='<span class="muted">Attachments are unavailable in this browser.</span>'}}
function attachDocuments(caseId){const input=document.createElement('input');input.type='file';input.accept='.pdf,.png,.jpg,.jpeg,.txt,.doc,.docx';input.multiple=true;input.onchange=async()=>{let added=0;try{for(const file of input.files){if(file.size>8*1024*1024){toast('Each document must be under 8 MB');continue}await docSave({id:uid(),caseId,name:file.name.slice(0,180),type:file.type||'application/octet-stream',size:file.size,date:today(),blob:file});added++}await renderAttachments(caseId);if(added)toast(`${added} document${added===1?'':'s'} attached`)}catch(e){toast('Could not attach. Check available device storage.')}};input.click()}
async function downloadAttachment(id){try{const d=await docGet(id);if(!d)return toast('Document unavailable');downloadBlob(d.blob,d.name)}catch(e){toast('Document unavailable')}}
async function deleteAttachment(id){try{await docDelete(id);await renderAttachments(ui.caseId);toast('Attachment removed')}catch(e){toast('Could not remove document')}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
const icsSafe=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);
function downloadICS(c){const d=c.due.replace(/-/g,''),day=new Date(c.due+'T12:00:00'),next=iso(addDays(day,1)).replace(/-/g,'');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AMP Personal Space//EN','BEGIN:VEVENT','UID:'+uid()+'@amp-personal-space','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/g,''),'DTSTART;VALUE=DATE:'+d,'DTEND;VALUE=DATE:'+next,'SUMMARY:'+icsSafe('Follow up: '+c.title),'DESCRIPTION:'+icsSafe(c.nextAction),'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY','DESCRIPTION:AMP follow-up','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');downloadBlob(new Blob([content],{type:'text/calendar;charset=utf-8'}),'amp-follow-up.ics');toast('Calendar file ready. Open it to add the reminder. This is not automatic syncing.')}
async function fileToDataURL(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(file)})}
async function exportAll(){try{toast('Preparing your backup…');const docs=await docsAll().catch(()=>[]);const files=[];for(const d of docs)files.push({id:d.id,caseId:d.caseId,name:d.name,type:d.type,size:d.size,date:d.date,data:await fileToDataURL(d.blob)});const payload={format:'amp-backup-v1',exportedAt:new Date().toISOString(),app,property,documents:files};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});downloadBlob(blob,'AMP-backup-'+today()+'.json');toast('Backup downloaded — store it securely')}catch(e){toast('Unable to create backup')}}
async function importAll(file){if(!file)return;if(file.size>70*1024*1024)return toast('Backup too large');try{const raw=JSON.parse(await file.text());if(raw?.format!=='amp-backup-v1'||!raw.app||!Array.isArray(raw.app.goals)||!Array.isArray(raw.app.habits)||!Array.isArray(raw.app.cases)||!raw.app.checks||!Array.isArray(raw.property?.properties)||!Array.isArray(raw.property?.transactions)||!Array.isArray(raw.documents))throw Error('Invalid format');if(!confirm('Replace ALL your current AMP data with this backup?'))return;for(const doc of raw.documents){if(typeof doc.data!=='string'||!/^data:[^,]*;base64,/.test(doc.data))throw Error('Invalid attached file');}const newDocs=[];for(const d of raw.documents){const [prefix,base64]=d.data.split(',',2);const mime=prefix.match(/^data:(.*?);base64$/)?.[1]||'application/octet-stream',binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);newDocs.push({id:String(d.id),caseId:String(d.caseId),name:String(d.name).slice(0,180),type:mime,size:bytes.length,date:String(d.date),blob:new Blob([bytes],{type:mime})})}await clearDocs();for(const d of newDocs)await docSave(d);app=raw.app;property=raw.property;save();closeModal();ui.page='home';ui.caseId=null;ui.goalId=null;ui.propertyId=null;render();toast('Backup restored')}catch(e){toast('That file is not a valid AMP backup')}}
// App startup
$('#main').addEventListener('click',handleAction);
$('#desktopNav').addEventListener('click',handleAction);
$('#mobileNav').addEventListener('click',handleAction);
$('.topbar').addEventListener('click',handleAction);
$('#modal').addEventListener('click',handleAction);
document.addEventListener('submit',handleSubmit);
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
$('#modal').addEventListener('close',()=>{ui.modal=null});
$('#importFile').addEventListener('change',async e=>{await importAll(e.target.files?.[0]);e.target.value=''});
window.addEventListener('storage',e=>{if(e.key===PROPERTY_KEY||e.key===AMP_KEY){load();render()}});
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);if(pageNames[name]&&name!==ui.page)go(name)});
// Waiting cases return to the action queue on the day after their follow-up date.
let dueUpdated=false;for(const c of app.cases){if(c.status==='waiting'&&c.due&&c.due<today()){c.status='action';c.history??=[];c.history.push({date:today(),title:'Follow-up due',body:'Returned to your action queue'});dueUpdated=true}}if(dueUpdated)save();
if(pageNames[location.hash.slice(1)])ui.page=location.hash.slice(1);
render();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
})();
